<?php
namespace App\Services\Reports;
use ZipArchive;
class XlsxWriter {
 private function xml(string $value):string {$value=preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u','',$value);return htmlspecialchars($value,ENT_XML1|ENT_QUOTES,'UTF-8');}
 private function col(int $n):string {$s='';while($n>0){$n--;$s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}
 private function cell(int $col,int $row,$value,string $type='text',int $style=0):string {
  $ref=$this->col($col).$row;if($type==='date'&&is_string($value)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)){ $days=(new \DateTimeImmutable('1899-12-30'))->diff(new \DateTimeImmutable($value))->days;return '<c r="'.$ref.'" s="3"><v>'.$days.'</v></c>'; }if($value!==''&&$value!==null&&in_array($type,['number','money'])&&is_numeric($value))return '<c r="'.$ref.'" s="'.($type==='money'?2:$style).'"><v>'.(float)$value.'</v></c>';
  $value=is_scalar($value)||$value===null?(string)$value:json_encode($value,JSON_UNESCAPED_UNICODE);return '<c r="'.$ref.'" s="'.$style.'" t="inlineStr"><is><t xml:space="preserve">'.$this->xml($value).'</t></is></c>';
 }
 public function write(array $report):string {
  $sheets=$report['sections'];$meta=[];foreach(['Reporte'=>$report['title'],'Código'=>$report['code'],'Emitido'=>$report['emitted_at'],'Usuario emisor'=>$report['actor'],'ID de emisión'=>$report['issue_id']??'']+$report['metadata'] as $k=>$v)$meta[]=['campo'=>$k,'valor'=>$v];foreach($report['notes'] as $note)$meta[]=['campo'=>'Nota','valor'=>$note];$sheets[]=['title'=>'Metadatos','columns'=>[['key'=>'campo','label'=>'Campo','type'=>'text'],['key'=>'valor','label'=>'Valor','type'=>'text']],'rows'=>$meta,'totals'=>[]];
  if($report['signatures'])$sheets[]=['title'=>'Firmas registradas','columns'=>array_map(fn($k)=>['key'=>$k,'label'=>$k,'type'=>'text'],['statement','name','role','date','origin']),'rows'=>$report['signatures'],'totals'=>[]];
  $directory=storage_path('app/private/report-temp');if(!is_dir($directory))mkdir($directory,0770,true);$path=tempnam($directory,'xlsx-');$zip=new ZipArchive();if($zip->open($path,ZipArchive::OVERWRITE)!==true)throw new \RuntimeException('No se pudo crear el archivo Excel.');
  $contentTypes='<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
  $workbook='<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$relations='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';
  foreach($sheets as $i=>$sheet){$n=$i+1;$name=mb_substr(preg_replace('/[\\\\\/\?\*\[\]:]/',' ',$sheet['title']),0,25).' '.$n;$workbook.='<sheet name="'.$this->xml($name).'" sheetId="'.$n.'" r:id="rId'.$n.'"/>';$relations.='<Relationship Id="rId'.$n.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$n.'.xml"/>';$contentTypes.='<Override PartName="/xl/worksheets/sheet'.$n.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';
   $xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>';
   foreach($sheet['columns'] as $j=>$c){$width=$c['type']==='text'?max(15,min(45,mb_strlen($c['label'])+12)):20;$xml.='<col min="'.($j+1).'" max="'.($j+1).'" width="'.$width.'" customWidth="1"/>';}$xml.='</cols><sheetData><row r="1">';foreach($sheet['columns'] as $j=>$c)$xml.=$this->cell($j+1,1,$c['label'],'text',1);$xml.='</row>';
   foreach($sheet['rows'] as $k=>$row){$xml.='<row r="'.($k+2).'">';foreach($sheet['columns'] as $j=>$c)$xml.=$this->cell($j+1,$k+2,$row[$c['key']]??'',$c['type']);$xml.='</row>';}
   if($sheet['totals']){$line=count($sheet['rows'])+3;$xml.='<row r="'.$line.'">';foreach($sheet['columns'] as $j=>$c)$xml.=$this->cell($j+1,$line,$j===0?'TOTAL / SALDO FINAL':($sheet['totals'][$c['key']]??''),$c['type'],1);$xml.='</row>';}
   $xml.='</sheetData><autoFilter ref="A1:'.$this->col(max(1,count($sheet['columns']))).max(1,count($sheet['rows'])+1).'"/><pageMargins left="0.3" right="0.3" top="0.5" bottom="0.5" header="0.3" footer="0.3"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/></worksheet>';$zip->addFromString('xl/worksheets/sheet'.$n.'.xml',$xml);
  }
  $workbook.='</sheets></workbook>';$relations.='<Relationship Id="style" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
  $zip->addFromString('[Content_Types].xml',$contentTypes.'</Types>');$zip->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/workbook.xml',$workbook);$zip->addFromString('xl/_rels/workbook.xml.rels',$relations);
  $zip->addFromString('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="yyyy-mm-dd"/></numFmts><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF6653CA"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"><alignment horizontal="right" vertical="top"/></xf><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"><alignment vertical="top"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
  $zip->close();$bytes=file_get_contents($path);unlink($path);return $bytes;
 }
}
